import { query } from '../config/db.js';
import { cache } from '../config/redis.js';

/**
 * Device identity + device-level ban rules (single source of truth).
 *
 * Model:
 *  - A physical device has ONE stable `device_id` generated by the mobile app
 *    (Android: ANDROID_ID, iOS: Keychain UUID) so it survives uninstall / reinstall.
 *  - Every successful login / registration upserts a (user_id, device_id) row in
 *    `user_devices`, so a device is "saved under" whichever account logs in on it.
 *  - A ban is applied to the HARDWARE `device_id` (all rows that share it), so the
 *    device is blocked for every account until a moderator/admin lifts the ban.
 *  - Different physical devices never share a `device_id`, so banning one device
 *    never affects another.
 */

export const DEVICE_BANNED_CODE = 'DEVICE_BANNED';
export const DEVICE_BANNED_MESSAGE =
  'This device has been banned from accessing the platform. Please contact support.';

const MAX_DEVICE_ID_LENGTH = 191; // user_devices.device_id VARCHAR(191)

/** Trim + clamp a raw device identifier coming from a client. Returns '' when unusable. */
export function normalizeDeviceId(raw) {
  if (raw === undefined || raw === null) return '';
  return String(raw).trim().slice(0, MAX_DEVICE_ID_LENGTH);
}

/** Read the device id a client sent (body or headers). */
export function extractDeviceId(req) {
  const body = req.body || {};
  return normalizeDeviceId(
    body.device_unique_id ||
      body.device_id ||
      body.deviceId ||
      body.deviceUniqueId ||
      req.headers['x-device-id'] ||
      req.headers['x-device-unique-id'] ||
      ''
  );
}

/** Read the device display name a client sent (body or headers). */
export function extractDeviceName(req) {
  const body = req.body || {};
  return String(
    body.device_name ||
      body.deviceName ||
      body.device_model ||
      body.deviceModel ||
      req.headers['x-device-name'] ||
      req.headers['x-device-model'] ||
      ''
  ).trim();
}

/**
 * Is this hardware device banned? Redis cache-aside over MySQL.
 * Any banned row for the device_id means the whole device is banned.
 */
export async function isDeviceBanned(deviceId) {
  const id = normalizeDeviceId(deviceId);
  if (!id) return false;
  return Boolean(
    await cache.getOrSet(`device:banned:${id}`, 300, async () => {
      const rows = await query(
        'SELECT id FROM user_devices WHERE device_id = ? AND is_banned = 1 LIMIT 1',
        [id]
      );
      return Boolean(rows && rows.length > 0);
    })
  );
}

/** Standard 403 body for a banned device. */
export function deviceBannedResponse(res) {
  return res.status(403).json({
    success: false,
    code: DEVICE_BANNED_CODE,
    message: DEVICE_BANNED_MESSAGE,
  });
}

/**
 * Save (upsert) this device under the given user.
 * Never throws: a failure to record the device must not break login.
 */
export async function registerUserDevice(userId, deviceId, info = {}) {
  const id = normalizeDeviceId(deviceId);
  if (!userId || !id) return false;
  try {
    await query(
      `INSERT INTO user_devices (user_id, device_id, device_model, os_type, os_version, app_version, ip_address, user_agent, last_login_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, NOW())
       ON DUPLICATE KEY UPDATE
         device_model = VALUES(device_model),
         os_type = VALUES(os_type),
         os_version = VALUES(os_version),
         app_version = VALUES(app_version),
         ip_address = VALUES(ip_address),
         user_agent = VALUES(user_agent),
         last_login_at = NOW()`,
      [
        userId,
        id,
        String(info.deviceName || 'Unknown Mobile Device').slice(0, 100),
        String(info.osType || 'Mobile').slice(0, 50),
        String(info.osVersion || '').slice(0, 50),
        String(info.appVersion || '1.0.0').slice(0, 50),
        String(info.ip || '').slice(0, 45),
        String(info.userAgent || '').slice(0, 255),
      ]
    );

    // A freshly saved row inherits the hardware's ban state, so a banned device
    // can never end up with an "unbanned" row under a different account.
    const banned = await query(
      'SELECT ban_reason, banned_by, banned_at FROM user_devices WHERE device_id = ? AND is_banned = 1 LIMIT 1',
      [id]
    );
    if (banned && banned.length > 0) {
      await query(
        `UPDATE user_devices SET is_banned = 1, ban_reason = ?, banned_by = ?, banned_at = ?
         WHERE device_id = ? AND user_id = ? AND is_banned = 0`,
        [banned[0].ban_reason, banned[0].banned_by, banned[0].banned_at, id, userId]
      );
    }
    return true;
  } catch (err) {
    console.error('[deviceService] registerUserDevice error:', err.message);
    return false;
  }
}

/** Build the info object registerUserDevice expects from an Express request. */
export function deviceInfoFromRequest(req, fallbackName = '') {
  const body = req.body || {};
  return {
    deviceName: extractDeviceName(req) || fallbackName,
    osType: body.osType || body.os_type || req.headers['x-os-type'] || 'Mobile',
    osVersion: body.osVersion || body.os_version || req.headers['x-os-version'] || '',
    appVersion: body.appVersion || body.app_version || req.headers['x-app-version'] || '1.0.0',
    ip: req.ip || req.headers['x-forwarded-for'] || req.socket?.remoteAddress || '',
    userAgent: req.headers['user-agent'] || '',
  };
}

/**
 * Ban or unban hardware devices. MySQL first (SSOT), then Redis.
 * Applies to EVERY row sharing the device_id (all accounts that used the device).
 * @returns {Promise<number>} affected row count
 */
export async function setDeviceBanState(deviceIds, banned, { reason = null, bannedBy = null } = {}) {
  const ids = [...new Set((Array.isArray(deviceIds) ? deviceIds : [deviceIds]).map(normalizeDeviceId).filter(Boolean))];
  if (ids.length === 0) return 0;

  const placeholders = ids.map(() => '?').join(',');
  const result = banned
    ? await query(
        `UPDATE user_devices SET is_banned = 1, ban_reason = ?, banned_by = ?, banned_at = NOW()
         WHERE device_id IN (${placeholders})`,
        [reason, bannedBy, ...ids]
      )
    : await query(
        `UPDATE user_devices SET is_banned = 0, ban_reason = NULL, banned_by = NULL, banned_at = NULL
         WHERE device_id IN (${placeholders})`,
        ids
      );

  // Redis only after MySQL succeeded
  for (const id of ids) {
    if (banned) {
      await cache.set(`device:banned:${id}`, true, 86400 * 30);
    } else {
      await cache.del(`device:banned:${id}`);
    }
  }
  await cache.delByPattern('moderator:banned_devices:*');
  return result?.affectedRows || 0;
}

/** All hardware device_ids ever saved under a user. */
export async function getUserDeviceIds(userId) {
  const rows = await query('SELECT DISTINCT device_id FROM user_devices WHERE user_id = ?', [userId]);
  return (rows || []).map((r) => r.device_id).filter(Boolean);
}
